import{_ as t,o as r,c as d,a2 as o}from"./chunks/framework.BWuWLRhz.js";const b=JSON.parse('{"title":"开发者手册","description":"","frontmatter":{},"headers":[],"relativePath":"zh-CN/dev-guide/index.md","filePath":"zh-CN/dev-guide/index.md","lastUpdated":1788104653000}'),a={name:"zh-CN/dev-guide/index.md"};function c(i,e,l,n,s,h){return r(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="开发者手册" tabindex="-1">开发者手册 <a class="header-anchor" href="#开发者手册" aria-label="Permalink to &quot;开发者手册&quot;">​</a></h1><p>欢迎查阅 Lertaro 开发者参考手册。Lertaro 采用先进的解耦架构与开放的插件化生态体系，提供了官方 SDK 程序集 <code>Lertaro.PluginSdk</code>。开发者可以通过引用该 SDK，为 Lertaro 贡献自定义搜索源、扩展右键上下文动作、深度适配第三方文件管理器与原生对话框，或者定制美化主题与文件预览组件。</p><h2 id="_1-架构与开发流程" tabindex="-1">1. 架构与开发流程 <a class="header-anchor" href="#_1-架构与开发流程" aria-label="Permalink to &quot;1. 架构与开发流程&quot;">​</a></h2><ul><li><strong><a href="./architecture.html">系统架构设计</a></strong> —— 详解 SYSTEM 级 Windows 索引服务、用户态 WPF 交互进程与独立键盘钩子进程的三进程隔离模型与命名管道 IPC 通信机制。</li><li><strong><a href="./getting-started.html">快速上手指南</a></strong> —— 从零创建插件类库工程、引用 SDK、实现 <code>IPlugin</code> 入口以及本地调试的最佳实践。</li><li><strong><a href="./packaging.html">打包与分发</a></strong> —— 插件程序集目录结构规范、第三方托管/原生依赖库打包、多语言 JSON 资源内嵌与 PostBuild 自动部署。</li><li><strong><a href="./examples.html">官方插件范例</a></strong> —— 深度剖析随包开源的 <code>CoreExtensions</code>、<code>PinyinAlias</code> 与 <code>FlowLauncherBridge</code> 等真实插件的最佳实践代码。</li></ul><h2 id="_2-插件-sdk-接口参考" tabindex="-1">2. 插件 SDK 接口参考 <a class="header-anchor" href="#_2-插件-sdk-接口参考" aria-label="Permalink to &quot;2. 插件 SDK 接口参考&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">SDK 模块分类</th><th style="text-align:left;">核心接口与服务</th><th style="text-align:left;">关键功能说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><a href="./sdk/core-search-actions.html">核心检索与动作</a></strong></td><td style="text-align:left;"><code>ISearchableItemProvider</code><br><code>IInstantResultProvider</code><br><code>IAliasProvider</code><br><code>IQueryTokenProvider</code><br><code>ISearchResultAction</code><br><code>IDynamicActionProvider</code></td><td style="text-align:left;">贡献静态索引源、高频即时计算答案、非 ASCII 别名转写引擎、尾部 Token 后缀处理器以及静态/动态上下文动作菜单。</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/system-adapters.html">系统与对话框适配</a></strong></td><td style="text-align:left;"><code>IActivePathCollector</code><br><code>IFileDialogAdapter</code><br><code>IInlineSearchAdapter</code><br><code>IQuickNavigationProvider</code></td><td style="text-align:left;">探测前台管理器活动目录、挂载原生文件对话框、内嵌搜索条并双向同步选中状态、贡献鼠标快速导航级联菜单。</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/ui-extensions.html">界面与预览扩展</a></strong></td><td style="text-align:left;"><code>ISidebarFilterProvider</code><br><code>IResultColumnProvider</code><br><code>IQuickPanelTabProvider</code><br><code>IFilePreviewProvider</code><br><code>IThumbnailProvider</code><br><code>IThemeProvider</code><br><code>ITranslationProvider</code></td><td style="text-align:left;">扩展侧边栏筛选分类、表格视图自定义列、快速面板动态工作区标签、QuickLook 自定义渲染器与缩略图提取、WPF 资源字典主题包与多语言 i18n。</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/abstractions.html">共享抽象契约</a></strong></td><td style="text-align:left;"><code>ISearchResult</code><br><code>FileMetadata</code><br><code>IPluginSearchWindow</code><br><code>IConfigurable</code></td><td style="text-align:left;">检索结果只读数据契约、纳秒级文件时间戳与大小元数据、宿主窗口安全控制句柄与基于模式驱动的原生配置表单。</td></tr><tr><td style="text-align:left;"><strong><a href="./sdk/services.html">宿主开放服务</a></strong></td><td style="text-align:left;"><code>FuzzyMatchService</code><br><code>TranslationService</code><br><code>IconService</code><br><code>FavoritesService</code><br><code>HistoryService</code><br><code>FileMetadataService</code><br><code>DirectoryIndexerService</code><br><code>RecentFilesService</code><br><code>ExplorerPathService</code><br><code>PluginSettingsService</code><br><code>SettingsSearchService</code><br><code>SettingsWindowService</code><br><code>SearchRefreshService</code><br><code>UserDataService</code><br><code>Logger</code></td><td style="text-align:left;">宿主暴露的高性能基础设施：fzf 模糊匹配与高亮掩码、多语言解析、带缓存图标提取、收藏管理与历史读取、后台目录索引代理、用户数据目录隔离及 Shell 原生文件操作。</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>本手册所有接口签名、方法参数与行为契约均直接对照 <code>Lertaro.PluginSdk</code> 源码严格编写并校验。</p></div>',7)])])}const S=t(a,[["render",c]]);export{b as __pageData,S as default};
